import{_ as r,a as o}from"./chunks/help-tips.DsVAi8vI.js";import{_ as s,o as a,c as n,a2 as e}from"./chunks/framework.Bzj1XTnB.js";const u=JSON.parse('{"title":"टिप्स, शॉर्टकट और सवाल","description":"ऐप के अंदर पाठ, काम के शॉर्टकट, कीबोर्ड की कुंजियाँ और आम सवालों के जवाब।","frontmatter":{"lang":"hi","slug":"tips-and-help","order":11,"title":"टिप्स, शॉर्टकट और सवाल","description":"ऐप के अंदर पाठ, काम के शॉर्टकट, कीबोर्ड की कुंजियाँ और आम सवालों के जवाब।"},"headers":[],"relativePath":"hi/tips-and-help.md","filePath":"hi/tips-and-help.md"}'),d={name:"hi/tips-and-help.md"};function i(p,t,l,g,h,c){return a(),n("div",null,[...t[0]||(t[0]=[e('<h1 id="टिप्स-शॉर्टकट-और-सवाल" tabindex="-1">टिप्स, शॉर्टकट और सवाल <a class="header-anchor" href="#टिप्स-शॉर्टकट-और-सवाल" aria-label="Permalink to &quot;टिप्स, शॉर्टकट और सवाल&quot;">​</a></h1><h2 id="ऐप-के-अंदर-पाठ" tabindex="-1">ऐप के अंदर पाठ <a class="header-anchor" href="#ऐप-के-अंदर-पाठ" aria-label="Permalink to &quot;ऐप के अंदर पाठ&quot;">​</a></h2><p><strong>Learn</strong> (होम स्क्रीन की नीचे की पट्टी) में छोटे पाठ हैं: फ़्रेम-दर-फ़्रेम की बुनियाद, फ़्रेम प्रति सेकंड, ओनियन स्किन, लेयर, लैसो और कॉपी-पेस्ट, रूलर और आईना, ऑडियो, मूवी बनाना और ऑब्जेक्ट लाइब्रेरी। किसी पाठ पर टैप करके उसके चरण देखें।</p><p><img src="'+r+'" alt="How to animate"></p><p>एडिटर में <strong>⋮ → Help &amp; tips</strong> हर टूल को एक-दो वाक्य में समझाता है।</p><p><img src="'+o+'" alt="Help and tips"></p><h2 id="काम-के-शॉर्टकट" tabindex="-1">काम के शॉर्टकट <a class="header-anchor" href="#काम-के-शॉर्टकट" aria-label="Permalink to &quot;काम के शॉर्टकट&quot;">​</a></h2><ul><li><strong>Brush पर डबल-टैप</strong> — रूलर चालू या बंद।</li><li><strong>Lasso पर डबल-टैप</strong> — लेयर पर सब कुछ चुनें।</li><li><strong>दो उँगलियों से टैप</strong> — अनडू। <strong>तीन उँगलियों से टैप</strong> — रीडू।</li><li><strong>फ़्रेम पर लॉन्ग-प्रेस</strong> — होल्ड, डुप्लिकेट, कॉपी, पेस्ट, हिलाना, शेयर।</li><li><strong>किसी भी बटन पर लॉन्ग-प्रेस</strong> — उसका नाम दिखता है।</li><li><strong>Copy, फिर दूसरे फ़्रेम पर Paste</strong> — ड्रॉइंग उसी जगह आती है।</li></ul><h2 id="कीबोर्ड-टैबलेट-और-कीबोर्ड-वाले-फ़ोन" tabindex="-1">कीबोर्ड (टैबलेट और कीबोर्ड वाले फ़ोन) <a class="header-anchor" href="#कीबोर्ड-टैबलेट-और-कीबोर्ड-वाले-फ़ोन" aria-label="Permalink to &quot;कीबोर्ड (टैबलेट और कीबोर्ड वाले फ़ोन)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>कुंजी</th><th>क्या होता है</th></tr></thead><tbody><tr><td>← / →</td><td>पिछला / अगला फ़्रेम</td></tr><tr><td>↑ / ↓</td><td>ऊपर वाली / नीचे वाली लेयर</td></tr><tr><td>Space</td><td>चलाएँ / रोकें</td></tr><tr><td>O</td><td>ओनियन स्किन चालू / बंद</td></tr><tr><td>B</td><td>Brush</td></tr><tr><td>E</td><td>Eraser</td></tr><tr><td>Ctrl + Z</td><td>अनडू</td></tr><tr><td>Ctrl + Shift + Z या Ctrl + Y</td><td>रीडू</td></tr></tbody></table><h2 id="सवाल" tabindex="-1">सवाल <a class="header-anchor" href="#सवाल" aria-label="Permalink to &quot;सवाल&quot;">​</a></h2><p><strong>क्या कैनवास का साइज़ बाद में बदल सकते हैं?</strong> नहीं — इसे प्रोजेक्ट बनाते समय चुनें। रफ़्तार, टाइमिंग, नाम और बैकग्राउंड कभी भी बदल सकते हैं।</p><p><strong>मैं और लेयर क्यों नहीं जोड़ पा रहा?</strong> एक प्रोजेक्ट में 15 लेयर तक हो सकती हैं। दो लेयर मिलाएँ (लेयर को बाईं ओर स्वाइप करके <strong>Merge</strong> टैप करें) या जो ज़रूरी नहीं उसे डिलीट करें।</p><p><strong>मेरे स्टिकर पैक पर &quot;Add to WhatsApp&quot; बटन काम नहीं कर रहा।</strong> बटन है, पर जब तक पैक में 3 स्टिकर न हों वह फीका रहता है — WhatsApp इससे कम नहीं लेता। उसी पैक में और स्टिकर बनाएँ।</p><p><strong>कैनवास के बाहर ले गई चीज़ गायब हो गई।</strong> जिस प्रोजेक्ट में कैनवास के चारों ओर जगह नहीं है, वहाँ कैनवास के बाहर का हिस्सा रखते ही कट जाता है। जगह पाने के लिए <strong>Project settings → Draw outside the canvas</strong> चालू करें (नए प्रोजेक्ट में पहले से चालू है)।</p><p><strong>मेरे फ़ोन पर Smooth zoom से कोई फ़र्क़ नहीं दिखता।</strong> इसके लिए Android 13 या नया चाहिए, और यह सिर्फ़ पास से ज़ूम करने पर दिखता है। देखें कि <strong>Settings → Smooth zoom</strong> चालू है।</p><p><strong>मेरी मूवी कहाँ हैं?</strong> होम स्क्रीन के <strong>Movies</strong> टैब में। फ़ोन की गैलरी में कॉपी रखने के लिए <strong>Save to gallery</strong> इस्तेमाल करें।</p><p><strong>अपने प्रोजेक्ट नए फ़ोन पर कैसे ले जाएँ?</strong> प्रोजेक्ट पर लॉन्ग-प्रेस करें → <strong>Export project</strong>, <code>.flippa</code> फ़ाइल नए फ़ोन पर भेजें, और उसे <strong>⋮ → Import project</strong> से खोलें।</p><p><strong>क्या मैं अपने FlipaClip प्रोजेक्ट खोल सकता हूँ?</strong> हाँ। FlipaClip से प्रोजेक्ट <code>.fc</code> फ़ाइल के रूप में एक्सपोर्ट करें, फिर Toonik में <strong>⋮ → Import project</strong> इस्तेमाल करें। ड्रॉइंग और लेयर आ जाती हैं।</p><p><strong>क्या अकाउंट चाहिए? क्या मेरी ड्रॉइंग कहीं अपलोड होती है?</strong> कोई अकाउंट नहीं चाहिए, और आपकी ड्रॉइंग आपके फ़ोन में ही रहती हैं। Toonik में सब कुछ मुफ़्त है।</p>',20)])])}const f=s(d,[["render",i]]);export{u as __pageData,f as default};
